{
  "question": "How do I apply for a job?",
  "answer": "Click the Apply button on any job listing and follow the steps.",
  "category": "general",
  "order": 1
}

{
  "messages": [
    {
      "role": "user",
      "content": "Find me React developer jobs in Dubai with salary above 15000 AED"
    }
  ],
  "context": "job_search"
}

{
  "text": "I am good at programming and worked on many projects",
  "context": "profile_summary"
}

{
  "query": "remote react jobs in UAE paying more than 15k"
}

{
  "query": "senior developers with 5+ years in React who are available immediately"
}

{
  "query": "applications rejected last week for engineering roles"
}

{
  "agentUserIds": [
    "{{agentId}}"
  ],
  "message": "Please update your pipeline status by EOD"
}

{
  "jobId": "{{jobId}}",
  "coverLetter": "I am excited to apply for this position. My 5 years of experience in React development..."
}

{
  "status": "shortlisted",
  "note": "Strong technical background",
  "employerNotes": "Schedule for interview next week"
}

{
  "content": "Had a great initial phone screening. Very articulate and enthusiastic.",
  "mentions": []
}

{
  "rating": 4,
  "comment": "The process was smooth and professional. Would recommend."
}

{
  "applicationIds": [
    "id1",
    "id2",
    "id3"
  ],
  "action": "reject",
  "params": {
    "rejectionReason": "Position has been filled. Thank you for your interest."
  }
}

{
  "companyName": "Acme Corp",
  "description": "Leading technology company in the MENA region",
  "industry": "Technology",
  "size": "200-500",
  "website": "https://acmecorp.com",
  "socialLinks": {
    "linkedin": "https://linkedin.com/company/acme"
  }
}

{
  "title": "Senior React Developer",
  "description": "We are looking for an experienced React developer...",
  "requirements": [
    "5+ years React",
    "TypeScript expertise",
    "Next.js experience"
  ],
  "salary": {
    "min": 15000,
    "max": 25000,
    "currency": "AED"
  },
  "skills": [
    "React",
    "TypeScript",
    "Next.js"
  ]
}

{
  "title": "Effective Interviewing",
  "content": "Best practices for conducting interviews...",
  "type": "guide",
  "isRequired": true
}

{
  "name": "Interview Invitation",
  "subject": "Interview Invitation - {{jobTitle}}",
  "body": "<p>Dear {{candidateName}},</p><p>We would like to invite you for an interview...</p>",
  "type": "email"
}

{
  "coverLetter": "I am excited to apply for this role. With 7 years of React experience..."
}

{
  "headline": "Senior Full Stack Developer | React & Node.js",
  "summary": "Passionate developer with 7 years of experience building scalable web applications...",
  "skills": [
    "React",
    "TypeScript",
    "Node.js",
    "PostgreSQL",
    "AWS"
  ],
  "experience": [
    {
      "title": "Senior Developer",
      "company": "Tech Corp",
      "from": "2022-01",
      "to": null,
      "current": true,
      "description": "Leading frontend development team"
    }
  ],
  "education": [
    {
      "degree": "BSc Computer Science",
      "institution": "University of Technology",
      "year": 2018,
      "grade": "3.8 GPA"
    }
  ],
  "languages": [
    {
      "language": "English",
      "level": "fluent"
    },
    {
      "language": "Arabic",
      "level": "native"
    }
  ],
  "preferredJobTypes": [
    "full_time",
    "contract"
  ],
  "preferredLocations": [
    "Dubai",
    "Abu Dhabi"
  ],
  "expectedSalary": {
    "min": 18000,
    "max": 25000,
    "currency": "AED"
  }
}

{
  "status": "completed",
  "outcome": "passed",
  "notes": "Excellent technical skills. Strong communication. Recommended for offer.",
  "feedback": "Very impressive candidate"
}

{
  "scores": {
    "technicalSkills": 8,
    "communication": 9,
    "cultureFit": 7,
    "problemSolving": 8,
    "motivation": 9
  },
  "overallRating": 8,
  "notes": "Strong technical foundation. Excellent communicator. Would be a great culture fit.",
  "recommendation": "strong_hire"
}

{
  "action": "cancel",
  "reason": "No longer needed",
  "feedback": "Great service but downsizing team"
}

{
  "planId": "{{planId}}",
  "userId": "{{userId}}",
  "autoRenew": true,
  "notes": "Premium plan assigned for enterprise client"
}

{
  "recipientId": "{{userId}}",
  "initialMessage": "Hello! I saw your profile and would like to discuss a potential opportunity."
}

{
  "content": "Thank you for your interest! When would be a good time to discuss this further?"
}

