  "subject": "Cannot upload CV",
  "category": "technical",
  "message": "I keep getting an error when trying to upload my CV. The file is a PDF under 5MB.",
  "priority": "medium"
}

{
  "status": "qualified",
  "notes": "Had discovery call. Budget confirmed. Ready to proceed.",
  "nextFollowUp": "2026-05-10"
}

{
  "action": "accept",
  "notes": "Happy to accept! Looking forward to starting."
}

{
  "email": {
    "jobAlerts": true,
    "applicationUpdates": true,
    "marketing": false
  },
  "push": {
    "messages": true,
    "interviews": true
  },
  "sms": {
    "interviews": true
  }
}

{
  "enabled": true,
  "filters": {
    "skills": [
      "React",
      "TypeScript"
    ],
    "location": "Dubai",
    "workMode": "remote",
    "salaryMin": 15000
  },
  "maxApplicationsPerDay": 5,
  "coverLetterTemplate": "I am interested in this position..."
}

{
  "jobUrl": "https://mployedin.com/jobs/senior-react-developer",
  "caption": "We are hiring a Senior React Developer! Join our amazing team.",
  "visibility": "public"
}
